package fraymus.workspace;

import org.json.*;
import org.junit.Test;
import java.nio.file.*;
import java.util.*;
import static org.junit.Assert.*;
import fraymus.factory.*;

public class CalibrationStoreTest {
    static JSONObject data(MeasurementStore measurements,SceneStore scenes,JSONObject scene,double friction) throws Exception {
        return data(measurements,scenes,scene,"friction",friction);
    }
    static JSONObject data(MeasurementStore measurements,SceneStore scenes,JSONObject scene,String parameter,double value) throws Exception {
        var definition=new JSONObject(scene.toString());definition.getJSONObject("parameters").put(parameter,value);
        var truth=scenes.calibrationRun(definition,.75,UUID.randomUUID().toString(),"fixture","synthetic-truth",()->false);
        var csv=new StringBuilder("time,distance\n");
        for(Object item:truth.getJSONArray("samples")){var p=(JSONObject)item;if(p.getInt("tick")%24==0)csv.append(p.getDouble("timeS")).append(",").append(p.getDouble("distanceM")).append("\n");}
        return measurements.importCsv(new JSONObject().put("title","Synthetic native trajectory "+value).put("filename","fixture.csv").put("csv",csv.toString())
            .put("sourceKind","synthetic").put("sourceNote","Generated by a separate Bullet world; not instrument measurements").put("missingPolicy","reject")
            .put("mapping",new JSONObject().put("timeColumn","time").put("distanceColumn","distance").put("timeUnit","s").put("distanceUnit","m")));
    }
    static void rewriteJob(Path root,String id,java.util.function.Consumer<JSONObject> edit) throws Exception {
        var schemas=new SchemaRegistry();schemas.register(new ComponentSchema("workspace.calibration",1,Map.of("payload",ComponentSchema.Kind.TEXT),Set.of("payload")));
        var disk=new WorldCheckpointStore(root.resolve("calibrations/jobs.fworld"));var world=new FactoryWorld(schemas);world.restore(disk.load(schemas).snapshot());
        var entity=world.snapshot().entities().stream().filter(e->e.id().toString().equals(id)).findFirst().orElseThrow();var c=entity.components().get(0);
        var job=new JSONObject(c.values().get("payload"));edit.accept(job);
        new WorldTransaction(world.snapshot()).add(new WorldTransaction.Put(entity.id(),new ComponentRecord(c.id(),c.type(),c.version(),Map.of("payload",job.toString())))).commit(world,schemas);disk.save(world.snapshot(),schemas);
    }
    @Test public void interruptedCheckpointResumesActualCompletedNativeOperationsWithoutDuplicates() throws Exception {
        var root=Files.createTempDirectory("calibration-resume-");try(var scenes=new SceneStore(root)){
            var m=new MeasurementStore(root);var a=scenes.save(new JSONObject());var b=scenes.save(new JSONObject().put("parameters",new JSONObject().put("angleDeg",35)));
            var t=data(m,scenes,a,.28);var v=data(m,scenes,b,.28);String id;JSONObject original;
            try(var store=new CalibrationStore(root,scenes,m)){id=store.start(request(a,b,t,v)).getString("id");original=settled(store,id);}
            int count=scenes.runs("").length();
            // Simulate losing job progress after completed native runs, retaining valid atomic native checkpoints.
            rewriteJob(root,id,j->{j.put("status","running").put("trials",new JSONArray()).put("completedNativeOperations",0);for(String k:List.of("baselineTraining","fittedTraining","selection","validationStartedAt","validationBaseline","validationFitted","evaluation"))j.remove(k);});
            try(var reopened=new CalibrationStore(root,scenes,m)){
                assertEquals("interrupted",reopened.read(id).getString("status"));var restored=settled(reopened,reopened.resume(id).getString("id"));
                assertEquals("completed",restored.getString("status"));assertTrue(restored.getJSONObject("evaluation").getBoolean("accepted"));
                assertEquals(count,scenes.runs("").length());assertEquals(original.getJSONObject("selection").getString("runId"),restored.getJSONObject("selection").getString("runId"));assertEquals(2,restored.getInt("attempts"));
            }
        }
    }
    @Test public void cancellationSettlesAndExplicitResumeWorks() throws Exception {
        var root=Files.createTempDirectory("calibration-cancel-");try(var scenes=new SceneStore(root)){
            var m=new MeasurementStore(root);var a=scenes.save(new JSONObject());var b=scenes.save(new JSONObject().put("parameters",new JSONObject().put("angleDeg",35)));
            var t=data(m,scenes,a,.28);var v=data(m,scenes,b,.28);
            try(var store=new CalibrationStore(root,scenes,m)){
                String id=store.start(request(a,b,t,v).put("seconds",10)).getString("id");store.cancel(id);var stopped=settled(store,id);assertEquals("cancelled",stopped.getString("status"));
                assertFalse(stopped.getBoolean("canApply"));assertThrows(IllegalStateException.class,()->store.report(id));
                var resumed=settled(store,store.resume(id).getString("id"));assertEquals(resumed.toString(),"completed",resumed.getString("status"));assertEquals(2,resumed.getInt("attempts"));
            }
        }
    }
    @Test public void atomicSceneReceiptReconcilesLostApplicationAcknowledgement() throws Exception {
        var root=Files.createTempDirectory("calibration-apply-recovery-");try(var scenes=new SceneStore(root)){
            var m=new MeasurementStore(root);var a=scenes.save(new JSONObject());var b=scenes.save(new JSONObject().put("parameters",new JSONObject().put("angleDeg",35)));
            var t=data(m,scenes,a,.28);var v=data(m,scenes,b,.28);String id;double selected;
            try(var store=new CalibrationStore(root,scenes,m)){var job=settled(store,store.start(request(a,b,t,v)).getString("id"));id=job.getString("id");selected=job.getJSONObject("selection").getDouble("value");}
            String operation=UUID.randomUUID().toString();rewriteJob(root,id,j->j.put("application",new JSONObject().put("applyOperationId",operation).put("status","apply-pending")));
            var receipt=scenes.applyCalibration(id,operation,a.getString("id"),1,b.getString("id"),1,"friction",selected);
            try(var reopened=new CalibrationStore(root,scenes,m)){
                assertEquals(receipt.toString(),reopened.read(id).getJSONObject("application").getJSONObject("applyReceipt").toString());
                reopened.apply(id);assertEquals(2,scenes.read(a.getString("id")).getInt("version"));reopened.rollback(id);assertEquals(3,scenes.read(a.getString("id")).getInt("version"));
            }
        }
    }
    @Test public void gravityFitUsesNativeRunsAndRejectsAStaleDatasetAtApplication() throws Exception {
        var root=Files.createTempDirectory("calibration-gravity-");try(var scenes=new SceneStore(root)){
            var m=new MeasurementStore(root);var a=scenes.save(new JSONObject());var b=scenes.save(new JSONObject().put("parameters",new JSONObject().put("angleDeg",35)));
            var t=data(m,scenes,a,"gravityMps2",12);var v=data(m,scenes,b,"gravityMps2",12);
            try(var store=new CalibrationStore(root,scenes,m)){
                var job=settled(store,store.start(request(a,b,t,v).put("parameter","gravityMps2").put("minimum",8).put("maximum",16)).getString("id"));
                assertTrue(job.toString(),job.getJSONObject("evaluation").getBoolean("accepted"));assertEquals(12,job.getJSONObject("selection").getDouble("value"),.02);
                m.importCsv(new JSONObject().put("id",t.getString("datasetId")).put("expectedVersion",1).put("title","Revised observations").put("filename","fixture.csv").put("csv",t.getString("csv")).put("sourceKind","synthetic").put("sourceNote","New version, same bytes").put("missingPolicy","reject").put("mapping",t.getJSONObject("mapping")));
                assertFalse(store.read(job.getString("id")).getBoolean("canApply"));assertThrows(ConcurrentModificationException.class,()->store.apply(job.getString("id")));
            }
        }
    }
    static JSONObject request(JSONObject a,JSONObject b,JSONObject train,JSONObject validation){
        return new JSONObject().put("trainingSceneId",a.getString("id")).put("trainingSceneVersion",a.getInt("version")).put("validationSceneId",b.getString("id")).put("validationSceneVersion",b.getInt("version"))
            .put("trainingDatasetId",train.getString("datasetId")).put("trainingDatasetVersion",train.getInt("version")).put("validationDatasetId",validation.getString("datasetId")).put("validationDatasetVersion",validation.getInt("version"))
            .put("parameter","friction").put("minimum",0).put("maximum",.8).put("seconds",.75).put("toleranceM",.015).put("minImprovementM",.001);
    }
    static JSONObject settled(CalibrationStore store,String id) throws Exception {
        long end=System.nanoTime()+60_000_000_000L;JSONObject job;
        do{job=store.read(id);if(!Set.of("running","queued").contains(job.getString("status")))return job;Thread.sleep(10);}while(System.nanoTime()<end);
        throw new AssertionError("Calibration did not settle");
    }
    @Test public void nativeFitHoldoutAndDurableIdempotentApplication() throws Exception {
        var root=Files.createTempDirectory("calibration-fit-");
        try(var scenes=new SceneStore(root)){
            var measurements=new MeasurementStore(root);var a=scenes.save(new JSONObject().put("parameters",new JSONObject().put("angleDeg",25)));
            var b=scenes.save(new JSONObject().put("parameters",new JSONObject().put("angleDeg",35)));var train=data(measurements,scenes,a,.28);var validation=data(measurements,scenes,b,.28);
            String id,applyId;JSONObject finished;
            try(var store=new CalibrationStore(root,scenes,measurements)){
                id=store.start(request(a,b,train,validation)).getString("id");finished=settled(store,id);
                assertEquals(finished.toString(),"completed",finished.getString("status"));assertTrue(finished.toString(),finished.getJSONObject("evaluation").getBoolean("accepted"));
                assertEquals(.28,finished.getJSONObject("selection").getDouble("value"),.004);assertTrue(finished.getInt("completedNativeOperations")<=20);
                assertTrue(finished.getJSONObject("selection").getString("frozenAt").compareTo(finished.getString("validationStartedAt"))<=0);
                assertEquals(1,scenes.read(a.getString("id")).getInt("version"));assertEquals(1,scenes.read(b.getString("id")).getInt("version"));
                for(Object item:finished.getJSONArray("trials")){var t=(JSONObject)item;var run=scenes.runRecord(t.getString("runId"));assertEquals(BulletRamp.BACKEND,run.getString("backend"));assertEquals(180,run.getJSONObject("final").getInt("tick"));
                    // Independent residual summation over exact retained sample timestamps.
                    double squares=0;for(Object row:train.getJSONArray("rows")){var p=(JSONObject)row;JSONObject sample=null;for(Object s:run.getJSONArray("samples"))if(Math.abs(((JSONObject)s).getDouble("timeS")-p.getDouble("timeS"))<1e-10)sample=(JSONObject)s;assertNotNull(sample);double r=sample.getDouble("distanceM")-p.getDouble("distanceM");squares+=r*r;}
                    assertEquals(Math.sqrt(squares/train.getJSONArray("rows").length()),t.getJSONObject("metrics").getDouble("rmseM"),1e-12);
                    assertThrows(IllegalArgumentException.class,()->measurements.compare(MeasurementStoreTest.binding(train,run,.1),scenes));
                }
                var report=store.report(id);assertTrue(report.getJSONObject("files").getString("index.html").contains("Accepted by declared gates"));
                try(var artifacts=new WorkspaceStore(root)){assertNotNull(artifacts.write(report).getString("id"));}
                var applied=store.apply(id);applyId=applied.getJSONObject("application").getJSONObject("applyReceipt").getString("id");
                assertEquals(2,scenes.read(a.getString("id")).getInt("version"));assertEquals(1,scenes.read(b.getString("id")).getInt("version"));
                assertTrue(a.getJSONObject("entityIds").similar(scenes.read(a.getString("id")).getJSONObject("entityIds")));
                assertEquals(applyId,store.apply(id).getJSONObject("application").getJSONObject("applyReceipt").getString("id"));
            }
            try(var reopened=new CalibrationStore(root,scenes,measurements)){
                assertEquals(applyId,reopened.read(id).getJSONObject("application").getJSONObject("applyReceipt").getString("id"));
                var undo=reopened.rollback(id);assertEquals(3,scenes.read(a.getString("id")).getInt("version"));assertEquals(0,scenes.read(a.getString("id")).getJSONObject("parameters").getDouble("friction"),0);
                assertEquals(undo.getJSONObject("application").getJSONObject("rollbackReceipt").getString("id"),reopened.rollback(id).getJSONObject("application").getJSONObject("rollbackReceipt").getString("id"));
                assertEquals(3,scenes.read(a.getString("id")).getInt("version"));
            }
        }
    }
    @Test public void validationCannotRetuneWinnerAndFailedGateCannotApply() throws Exception {
        var root=Files.createTempDirectory("calibration-heldout-");
        try(var scenes=new SceneStore(root)){
            var m=new MeasurementStore(root);var a=scenes.save(new JSONObject());var b=scenes.save(new JSONObject().put("parameters",new JSONObject().put("angleDeg",35)));
            var train=data(m,scenes,a,.28);var good=data(m,scenes,b,.28);var bad=data(m,scenes,b,.65);
            try(var store=new CalibrationStore(root,scenes,m)){
                var first=settled(store,store.start(request(a,b,train,good)).getString("id"));var second=settled(store,store.start(request(a,b,train,bad)).getString("id"));
                assertEquals(first.getJSONObject("selection").getDouble("value"),second.getJSONObject("selection").getDouble("value"),0);
                assertFalse(second.getJSONObject("evaluation").getBoolean("accepted"));assertThrows(IllegalStateException.class,()->store.apply(second.getString("id")));
            }
        }
    }
    @Test public void invalidBindingsDuplicatesAndStationaryDataHaveNoTrialEffects() throws Exception {
        var root=Files.createTempDirectory("calibration-invalid-");try(var scenes=new SceneStore(root)){
            var m=new MeasurementStore(root);var a=scenes.save(new JSONObject());var b=scenes.save(new JSONObject().put("parameters",new JSONObject().put("angleDeg",35)));
            var t=data(m,scenes,a,.28);var v=data(m,scenes,b,.28);var duplicate=m.importCsv(new JSONObject().put("title","Copied source").put("filename","copy.csv").put("csv",t.getString("csv")).put("sourceKind","synthetic").put("sourceNote","Copied normalized observations").put("missingPolicy","reject").put("mapping",t.getJSONObject("mapping")));
            try(var store=new CalibrationStore(root,scenes,m)){
                int count=scenes.runs("").length();var r=request(a,b,t,v);
                assertThrows(IllegalArgumentException.class,()->store.start(new JSONObject(r.toString()).put("validationDatasetId",t.getString("datasetId"))));
                assertThrows(IllegalArgumentException.class,()->store.start(new JSONObject(r.toString()).put("validationDatasetId",duplicate.getString("datasetId"))));
                assertThrows(IllegalArgumentException.class,()->store.start(new JSONObject(r.toString()).put("maximum",2)));
                assertThrows(IllegalArgumentException.class,()->store.start(new JSONObject(r.toString()).put("seconds",.1)));
                assertThrows(ConcurrentModificationException.class,()->store.start(new JSONObject(r.toString()).put("trainingSceneVersion",2)));
                assertEquals(count,scenes.runs("").length());assertEquals(0,store.list().length());
            }
        }
    }
    @Test public void stationaryAndOverlappingRecordsAreRejectedAndSourceNotesAreEscaped() throws Exception {
        var root=Files.createTempDirectory("calibration-source-");try(var scenes=new SceneStore(root)){
            var m=new MeasurementStore(root);var a=scenes.save(new JSONObject());var b=scenes.save(new JSONObject().put("parameters",new JSONObject().put("angleDeg",35)));
            var t=data(m,scenes,a,.28);var v=data(m,scenes,b,.28);
            var stationary=m.importCsv(new JSONObject().put("title","Stationary").put("filename","stationary.csv").put("csv","time,distance\n0,1\n.2,1\n.5,1\n").put("sourceKind","synthetic").put("sourceNote","Stationary observations").put("missingPolicy","reject").put("mapping",t.getJSONObject("mapping")));
            var first=t.getJSONArray("rows").getJSONObject(1);var overlap=m.importCsv(new JSONObject().put("title","Partial overlap").put("filename","partial.csv").put("csv","time,distance\n0,0\n"+first.getDouble("timeS")+","+first.getDouble("distanceM")+"\n.7,2\n").put("sourceKind","synthetic").put("sourceNote","Overlapping records").put("missingPolicy","reject").put("mapping",t.getJSONObject("mapping")));
            var unsafe=m.importCsv(new JSONObject().put("title","<script>test</script>").put("filename","unsafe.csv").put("csv",v.getString("csv")).put("sourceKind","synthetic").put("sourceNote","<img src=x onerror=alert(1)>").put("missingPolicy","reject").put("mapping",v.getJSONObject("mapping")));
            try(var store=new CalibrationStore(root,scenes,m)){
                int count=scenes.runs("").length();assertThrows(IllegalArgumentException.class,()->store.start(request(a,b,t,stationary)));assertThrows(IllegalArgumentException.class,()->store.start(request(a,b,t,overlap)));assertEquals(count,scenes.runs("").length());
                var job=settled(store,store.start(request(a,b,t,unsafe)).getString("id"));var html=store.report(job.getString("id")).getJSONObject("files").getString("index.html");
                assertFalse(html.contains("<script>"));assertFalse(html.contains("<img src=x"));assertTrue(html.contains("&lt;script&gt;test"));assertTrue(html.contains("&lt;img"));
                var repeated=settled(store,store.start(request(a,b,t,unsafe)).getString("id"));assertTrue(repeated.getJSONObject("definition").getInt("validationPriorUseCount")>=1);
            }
        }
    }
    @Test public void changedSceneBlocksApplyAndChangedAppliedSceneBlocksRollback() throws Exception {
        var root=Files.createTempDirectory("calibration-stale-");try(var scenes=new SceneStore(root)){
            var m=new MeasurementStore(root);var a=scenes.save(new JSONObject());var b=scenes.save(new JSONObject().put("parameters",new JSONObject().put("angleDeg",35)));
            var t=data(m,scenes,a,.28);var v=data(m,scenes,b,.28);
            try(var store=new CalibrationStore(root,scenes,m)){
                var job=settled(store,store.start(request(a,b,t,v)).getString("id"));assertTrue(job.getJSONObject("evaluation").getBoolean("accepted"));store.apply(job.getString("id"));
                scenes.save(new JSONObject().put("id",a.getString("id")).put("expectedVersion",2).put("parameters",new JSONObject().put("massKg",2).put("friction",0)));
                assertFalse(store.read(job.getString("id")).getBoolean("canRollback"));assertThrows(ConcurrentModificationException.class,()->store.rollback(job.getString("id")));
                var fresh=scenes.read(a.getString("id"));var next=settled(store,store.start(request(fresh,b,t,v)).getString("id"));
                scenes.save(new JSONObject().put("id",b.getString("id")).put("expectedVersion",1).put("parameters",new JSONObject().put("massKg",3)));
                assertFalse(store.read(next.getString("id")).getBoolean("canApply"));assertThrows(ConcurrentModificationException.class,()->store.apply(next.getString("id")));
            }
        }
    }
}
